create or replace function public.layer2_run_batch_context(p_batch_id uuid) returns jsonb language sql stable security definer set search_path=pg_catalog,pipeline as $$ select jsonb_build_object('batch',jsonb_build_object('id',b.id,'profile_id',b.profile_id,'profile_version_id',b.profile_version_id,'trigger_type',b.trigger_type,'status',b.status,'started_at',b.started_at,'policy_snapshot',b.policy_snapshot),'profile',jsonb_build_object('id',p.id,'domain',p.domain,'profile_key',p.profile_key,'enabled',p.enabled,'paused',p.paused),'items',coalesce((select jsonb_agg(jsonb_build_object('id',i.id,'entity_type',i.entity_type,'entity_id',i.entity_id,'source_url',i.source_url,'status',i.status,'selected_provider_id',i.selected_provider_id,'provider_key',ap.provider_key,'provider_enabled',ap.enabled,'unit_cost_usd',case when (ap.billing_config->>'unit_cost_usd') ~ '^-?[0-9]+(\.[0-9]+)?$' then (ap.billing_config->>'unit_cost_usd')::numeric else null end) order by i.created_at) from pipeline.layer2_run_items i left join pipeline.layer2_acquisition_providers ap on ap.id=i.selected_provider_id where i.batch_id=b.id),'[]'::jsonb)) from pipeline.layer2_run_batches b join pipeline.layer2_source_profiles p on p.id=b.profile_id where b.id=p_batch_id; $$; revoke all on function public.layer2_run_batch_context(uuid) from public,anon,authenticated; grant execute on function public.layer2_run_batch_context(uuid) to service_role;
create or replace function public.layer2_run_batch_start(p_batch_id uuid) returns boolean language plpgsql security definer set search_path=pg_catalog,pipeline as $$ begin if current_user not in ('service_role','postgres') then raise exception 'service_role required' using errcode='42501'; end if; update pipeline.layer2_run_batches set status='running',started_at=coalesce(started_at,now()) where id=p_batch_id and status in ('queued','running','partial'); return found; end $$; revoke all on function public.layer2_run_batch_start(uuid) from public,anon,authenticated; grant execute on function public.layer2_run_batch_start(uuid) to service_role;
create or replace function public.layer2_run_item_mark(p_item_id uuid,p_status text,p_job_id uuid default null,p_evidence_count integer default null,p_vendor_units numeric default null,p_vendor_cost_usd numeric default null,p_fields_targeted integer default null,p_fields_resolved integer default null,p_blocker text default null) returns boolean language plpgsql security definer set search_path=pg_catalog,pipeline as $$ begin if current_user not in ('service_role','postgres') then raise exception 'service_role required' using errcode='42501'; end if; if p_status not in ('queued','discovering','acquiring','extracting','resolved_l2','layer3_required','blocked','cancelled') then raise exception 'invalid item status'; end if; update pipeline.layer2_run_items set status=p_status,job_id=coalesce(p_job_id,job_id),evidence_count=coalesce(p_evidence_count,evidence_count),vendor_units=coalesce(p_vendor_units,vendor_units),vendor_cost_usd=coalesce(p_vendor_cost_usd,vendor_cost_usd),fields_targeted=coalesce(p_fields_targeted,fields_targeted),fields_resolved=coalesce(p_fields_resolved,fields_resolved),blocker=p_blocker,started_at=case when p_status in ('acquiring','extracting') then coalesce(started_at,now()) else started_at end,completed_at=case when p_status in ('resolved_l2','layer3_required','blocked','cancelled') then now() else null end where id=p_item_id; return found; end $$; revoke all on function public.layer2_run_item_mark(uuid,text,uuid,integer,numeric,numeric,integer,integer,text) from public,anon,authenticated; grant execute on function public.layer2_run_item_mark(uuid,text,uuid,integer,numeric,numeric,integer,integer,text) to service_role;
